<?php
require_once __DIR__.'/../includes/functions.php';require_role(['super_admin','admin','doctor']);$u=current_user();$sql="SELECT rx.*,mr.patient_id,mr.diagnosis,COALESCE(NULLIF(p.full_name,''),pu.name,'Patient') patient_name,du.name doctor_name,p.patient_number FROM prescriptions rx JOIN medical_records mr ON mr.id=rx.medical_record_id JOIN patients p ON p.id=mr.patient_id LEFT JOIN users pu ON pu.id=p.user_id JOIN doctors d ON d.id=rx.doctor_id JOIN users du ON du.id=d.user_id";$params=[];if($u['role']==='doctor'){$d=doctor_for_user($u['id']);$sql.=' WHERE rx.doctor_id=?';$params[]=(int)($d['id']??0);}$sql.=' ORDER BY rx.issued_at DESC LIMIT 250';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$pageTitle='Prescriptions';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Clinical care','Prescriptions','Medication instructions recorded by clinicians');?>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Prescription</th><th>Patient</th><th>Doctor</th><th>Diagnosis</th><th>Issued</th><th>Items</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong data-no-i18n><?=e($r['prescription_number'])?></strong></td><td><span data-no-i18n><?=e($r['patient_name'])?></span><div class="small-muted" data-no-i18n><?=e($r['patient_number'])?></div></td><td><span data-no-i18n><?=e($r['doctor_name'])?></span></td><td data-no-i18n><?=e(mb_strimwidth($r['diagnosis'],0,70,'…'))?></td><td data-no-i18n><?=e(substr($r['issued_at'],0,10))?></td><td><?php $i=db()->prepare('SELECT medicine_name,dosage,frequency,duration FROM prescription_items WHERE prescription_id=?');$i->execute([$r['id']]);foreach($i->fetchAll() as $it):?><div data-no-i18n><strong><?=e($it['medicine_name'])?></strong><div class="small-muted"><?=e($it['dosage'])?> · <?=e($it['frequency'])?> · <?=e($it['duration'])?></div></div><?php endforeach;?></td></tr><?php endforeach;?><?php if(!$rows)echo empty_row(6);?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>